import { useMemo } from 'react';

import { TableDataType, TableRowType } from 'components/Table/types';

interface UseRefreshStatusProps {
  showOnlyLE: boolean;
  data: TableDataType;
}

type RowWithRefreshStatus = Record<
  string,
  Record<string, Record<string, string>>
>;

const isLE = (row: TableRowType): boolean =>
  (row as RowWithRefreshStatus)['refresh_status']?.tag?.value === 'LE';

export const useRefreshStatus = ({
  showOnlyLE,
  data,
}: UseRefreshStatusProps) => {
  const filteredData = useMemo<TableDataType>(
    () => ({
      ...data,
      rows: data.rows.map((group) => (showOnlyLE ? group.filter(isLE) : group)),
    }),
    [data, showOnlyLE],
  );

  return { filteredData };
};
